const fs = require('fs');
const path = require('path');

const { handleIncomingMessage } = require('../../modules/ai/handleIncomingMessage');
const { fallbackResponse } = require('../../modules/ai/fallback');
const sendWhatsApp = require('../../services/whatsapp.unified');

console.log('🚀 AFRI QUEUE ENGINE v4 (PERSISTENT DISTRIBUTED CORE)');

const STORE = path.join(__dirname, 'store.queue.json');

function loadQueue() {
  try {
    return JSON.parse(fs.readFileSync(STORE, 'utf8'));
  } catch {
    return [];
  }
}

function saveQueue(q) {
  fs.writeFileSync(STORE, JSON.stringify(q, null, 2));
}

let queue = loadQueue();
let processing = false;

function persist() {
  saveQueue(queue);
}

function normalize(job) {
  return {
    id: job.id || Date.now() + '_' + Math.random().toString(36).slice(2),
    from: job.from || 'unknown',
    message: job.message || '',
    status: job.status || 'pending',
    retries: job.retries || 0
  };
}

function delay(ms) {
  return new Promise(r => setTimeout(r, ms));
}

async function safeAI(job) {
  try {
    const res = await Promise.race([
      handleIncomingMessage(job),
      new Promise((_, reject) => setTimeout(() => reject(new Error('AI_TIMEOUT')), 8000))
    ]);

    if (!res?.reply) throw new Error('Invalid AI response');
    return res;

  } catch (e) {
    console.log('⚠️ AI FALLBACK:', e.message);
    return fallbackResponse(job);
  }
}

async function processJob(job) {
  job.status = 'processing';
  persist();

  try {
    const ai = await safeAI(job);

    await sendWhatsApp({
      to: job.from,
      message: ai.reply
    });

    job.status = 'done';
    persist();

  } catch (err) {
    job.retries += 1;

    if (job.retries <= 3) {
      console.log('🔁 RETRY JOB:', job.id);
      job.status = 'pending';
    } else {
      console.log('💀 DEAD LETTER:', job.id);
      job.status = 'failed';
    }

    persist();
  }
}

async function processQueue() {
  if (processing) return;
  processing = true;

  while (queue.length > 0) {
    const job = normalize(queue.shift());
    await processJob(job);
    await delay(200);
  }

  processing = false;
}

function replayUnfinished() {
  queue = queue.filter(j => j.status !== 'done');
  persist();
}

function enqueue(job) {
  const safeJob = normalize(job);
  queue.push(safeJob);
  persist();
  processQueue();
}

// 🔥 BOOT RECOVERY
replayUnfinished();

module.exports = {
  enqueue,
  processQueue
};
